import qrcode from 'qrcode-generator'

/**
 * A QR code as SVG squares in the text colour, so it follows the palette.
 *
 * Encoded here, from a bundled encoder: the kiosk asks nothing of the
 * internet, and a code generated by a web service would be one more thing
 * that fails exactly when the second iPad needs setting up.
 */
export function qrPath(text: string): { size: number; path: string } {
  const code = qrcode(0, 'M')
  code.addData(text)
  code.make()
  const size = code.getModuleCount()
  let path = ''
  for (let row = 0; row < size; row += 1) {
    for (let col = 0; col < size; col += 1) {
      if (code.isDark(row, col)) {
        path += `M${col} ${row}h1v1h-1z`
      }
    }
  }
  return { size, path }
}

export default function QrCode({ text, size = 160, label }: { text: string; size?: number; label: string }) {
  const code = qrPath(text)
  // Four modules of quiet zone, which is what a camera needs to find it.
  const quiet = 4
  const box = code.size + quiet * 2
  return (
    <svg
      className="qr"
      role="img"
      aria-label={label}
      width={size}
      height={size}
      viewBox={`${-quiet} ${-quiet} ${box} ${box}`}
      shapeRendering="crispEdges"
    >
      <rect x={-quiet} y={-quiet} width={box} height={box} fill="var(--card)" />
      <path d={code.path} fill="var(--fg)" />
    </svg>
  )
}
